async importKeyDataSilent(window, keyData, isBinary, onlyFingerprint = "") {
  const errorMsgObj = {};
  let exitStatus = -1;
  try {
    exitStatus = await EnigmailKeyRing.importKeyAsync(
      window,
      false,
      keyData,
      isBinary,
      "",
      errorMsgObj,
      undefined,
      false,
      onlyFingerprint ? [onlyFingerprint] : []
    );
    this.clearCache();
  } catch (ex) {
    lazy.log.warn("Importing key FAILED!", ex);
  }
  return exitStatus === 0;
},
